import { prisma } from "@/lib/prisma";
import AppShell from "@/components/AppShell";
import FeeForm from "./FeeForm";
import FeeRecords from "./FeeRecords";

export default async function FeesPage() {
  const [students, fees] = await Promise.all([
    prisma.student.findMany({
      orderBy: { name: "asc" },
    }),
    prisma.fee.findMany({
      include: { student: true },
      orderBy: { dueDate: "asc" },
    }),
  ]);

  const formattedFees = fees.map((fee) => ({
    id: fee.id,
    studentName: fee.student.name,
    admissionNo: fee.student.admissionNo,
    academicYear: fee.academicYear,
    amount: Number(fee.amount),
    paidAmount: Number(fee.paidAmount),
    status: String(fee.status),
    dueDate: fee.dueDate.toISOString(),
  }));

  return (
    <AppShell>
      <div className="min-h-screen w-full bg-[#f5f7fb] px-4 py-6 sm:px-6 lg:px-8">

        {/* HEADER */}
        <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-center">
          <div>
            <p className="mb-2 text-xs font-bold uppercase tracking-[0.18em] text-blue-600">
              EDUMANAGE / FINANCE
            </p>

            <h1 className="text-3xl font-extrabold text-[#111827]">
              Fees Management
            </h1>

            <p className="mt-2 text-sm text-slate-500">
              Track tuition fees, payments and outstanding balances.
            </p>
          </div>

          <div className="flex items-center gap-3 rounded-2xl border border-slate-200 bg-white px-5 py-3 shadow-sm">
            <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-emerald-600 text-xl text-white">
              ₹
            </div>

            <div>
              <p className="text-xs text-slate-500">Fee Records</p>
              <p className="text-xl font-extrabold text-[#111827]">
                {fees.length}
              </p>
            </div>
          </div>
        </div>

        {/* HERO */}
        <section className="relative mb-8 overflow-hidden rounded-3xl bg-[#111827] p-7 text-white shadow-xl sm:p-9">
          <div className="relative z-10 max-w-xl">
            <span className="rounded-full border border-emerald-400/30 bg-emerald-500/15 px-3 py-1 text-xs font-bold tracking-wider text-emerald-300">
              FINANCE MANAGEMENT
            </span>

            <h2 className="mt-5 text-2xl font-extrabold sm:text-3xl">
              Smart Fee Management, Simplified.
            </h2>

            <p className="mt-3 text-sm leading-7 text-slate-300">
              Manage student payments, monitor pending fees and
              maintain transparent financial records.
            </p>
          </div>

          <div className="absolute -right-12 -top-24 h-72 w-72 rounded-full border-[40px] border-blue-500/10" />
          <div className="absolute -bottom-32 right-32 h-64 w-64 rounded-full bg-emerald-500/10 blur-3xl" />
          <div className="absolute bottom-0 right-0 h-1 w-full bg-gradient-to-r from-blue-600 via-emerald-500 to-transparent" />
        </section>

        {/* ADD FEE FORM */}
        <section className="mb-8 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
          <div className="border-b border-slate-100 bg-[#111827] px-5 py-5">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-600 text-xl text-white">
                +
              </div>

              <div>
                <h2 className="font-bold text-white">Add Fee Record</h2>
                <p className="mt-1 text-xs text-slate-300">
                  Create a new student fee record
                </p>
              </div>
            </div>
          </div>

          <div className="p-5">
            <FeeForm
              students={students.map((s) => ({
                id: s.id,
                name: s.name,
                admissionNo: s.admissionNo,
              }))}
            />
          </div>
        </section>

        {/* INTERACTIVE FEE RECORDS */}
        <FeeRecords fees={formattedFees} />

        {/* FOOTER */}
        <footer className="mt-8 border-t border-slate-200 py-5 text-center text-xs text-slate-400">
          EduManage © 2026 · Fee Management System
        </footer>

      </div>
    </AppShell>
  );
}